import pytest
from rest_framework.test import APIClient

pytestmark = pytest.mark.django_db


@pytest.fixture
def client():
    return APIClient()


def test_an_empty_workgroup_has_no_projects(client):
    assert client.get("/api/projects/?workgroup=empty").json() == []


@pytest.mark.parametrize("n", range(1, 9))
def test_a_workgroup_sees_only_its_projects(client, n):
    for i in range(n):
        client.post("/api/projects/", {"name": f"Lung CT {i}", "workgroup": "lab-a"}, format="json")
    client.post("/api/projects/", {"name": "Other", "workgroup": "lab-b"}, format="json")
    assert len(client.get("/api/projects/?workgroup=lab-a").json()) == n


def test_a_project_needs_a_name(client):
    response = client.post("/api/projects/", {"name": "", "workgroup": "lab-a"}, format="json")
    assert response.status_code == 400
